<?php declare(strict_types=1); namespace Annam; $title='Categories'; ?>
<div class="o-actions"><a class="o-btn o-btn-primary" href="/manage/categories/new/">+ Add category</a><?php foreach(['populated'=>'With items','empty'=>'Empty categories','all'=>'All categories'] as $k=>$v): ?><a class="o-btn <?= $scope===$k?'o-btn-primary':'' ?>" href="?category_view=<?= e($k) ?>"><?= e($v) ?></a><?php endforeach; ?></div><form class="o-filters"><input name="q" value="<?= e($query) ?>" placeholder="Search categories"><input type="hidden" name="category_view" value="<?= e($scope) ?>"><button class="o-btn">Search</button></form>
<div class="o-table-wrap"><table class="o-table"><thead><tr><th>Category</th><th>Items</th><th>Manage</th></tr></thead><tbody><?php foreach($records as $r): ?><tr><td><a href="/manage/categories/<?= e($r['id']) ?>/items/?status=1&amp;stock=1"><strong><?= e($r['name']) ?></strong></a></td><td><a href="/manage/categories/<?= e($r['id']) ?>/items/?status=1&stock=1"><?= e($r['website']) ?> on website</a><small><a href="/manage/categories/<?= e($r['id']) ?>/items/"><?= e($r['total']) ?> total including hidden items</a></small></td><td><a class="o-btn" href="/manage/categories/<?= e($r['id']) ?>/items/?status=1&amp;stock=1">Manage items</a> <a href="/manage/categories/<?= e($r['id']) ?>/">Edit category</a></td></tr><?php endforeach; ?><?php if(!$records): ?><tr><td colspan="3">No matching categories.</td></tr><?php endif; ?></tbody></table></div>